<template>
  <div class="templateDetail"><p>{{ definition.description }}</p><p v-if="definition.tags.length" class="muted">标签：{{ definition.tags.join('、') }}</p><h3>输入要求</h3><ul><li v-for="input in definition.inputs" :key="input.key"><strong>{{ input.label }}</strong> · {{ input.required ? '必填' : '可留空' }}<pre v-if="input.defaultValue">默认值：{{ input.defaultValue }}</pre></li></ul><ul v-if="definition.mediaInputs.length"><li v-for="input in definition.mediaInputs" :key="input.key">{{ input.label }} · {{ labels[input.mediaType] }} · {{ input.required ? '必须提供' : '可选' }}<p>{{ input.description }}</p></li></ul><h3>推荐流程</h3><ol><li v-for="(step, index) in definition.workflow" :key="index"><strong>{{ step.title }}</strong><p>{{ step.description }}</p></li></ol><h3>模型位置</h3><ul><li v-for="slot in definition.modelSlots" :key="slot.key"><strong>{{ slot.label }} · {{ labels[slot.mediaType] }}</strong><p>{{ slot.purpose }}</p><p v-if="slot.suggestedModelId">模型提示：{{ slot.suggestedModelId }}</p></li></ul><h3>样例制作单元：{{ definition.example.name }}</h3><p class="muted">{{ definition.example.output.width }} × {{ definition.example.output.height }} · {{ definition.example.output.frameRate }} 帧/秒 · {{ definition.example.shots.length }} 个镜头 · {{ definition.example.assets.length }} 个参考素材</p><details v-if="definition.example.assets.length"><summary>参考素材与版本关系</summary><section v-for="asset in definition.example.assets" :key="asset.key"><h4>{{ asset.name }} · {{ asset.versions.length }} 个版本</h4><div v-for="(version, index) in asset.versions" :key="version.key"><strong>版本 {{ index + 1 }}{{ version.parentKey ? ' · 基于版本' + (asset.versions.findIndex(item => item.key === version.parentKey) + 1) : '' }}</strong><pre>{{ version.description }}</pre><pre v-if="version.text">{{ version.text }}</pre></div></section></details><details v-for="(shot, index) in definition.example.shots" :key="shot.key"><summary>{{ index + 1 }}. {{ shot.title }} · 预计 {{ shot.expectedDuration }} 秒</summary><p>模型位置：{{ definition.modelSlots.find(slot => slot.key === shot.modelSlotKey)?.label }}</p><pre>{{ shot.story }}</pre><pre v-if="shot.dialogue">对白：{{ shot.dialogue }}</pre><pre>提示词：{{ shot.prompt }}</pre><ul><li v-for="(reference, refIndex) in shot.references" :key="refIndex">{{ referenceLabel(reference.assetKey, reference.versionKey) }} · {{ reference.role }}</li></ul></details><details v-for="node in definition.example.generationNodes" :key="node.key"><summary>辅助创作：{{ node.title }}</summary><p>{{ definition.modelSlots.find(slot => slot.key === node.modelSlotKey)?.label }}</p><pre>{{ node.prompt }}</pre><ul><li v-for="(reference, index) in node.references" :key="index">{{ referenceLabel(reference.assetKey, reference.versionKey) }} · {{ reference.role }}</li></ul></details></div>
</template>

<script setup lang="ts">
import type { ProductionTemplate } from "@toonflow/server/productionTemplates";
const props = defineProps<{ definition: ProductionTemplate }>(); const labels = { image: "图片", video: "视频", audio: "音频" };
function referenceLabel(assetKey: string, versionKey: string) { const asset = props.definition.example.assets.find(item => item.key === assetKey); return `${asset?.name ?? '参考'} · 版本${(asset?.versions.findIndex(item => item.key === versionKey) ?? -1) + 1}`; }
</script>

<style scoped lang="scss">
.templateDetail { min-width: 0; font-size: 13px; line-height: 1.8; overflow-wrap: anywhere; h3 { font-size: 15px; margin: 24px 0 10px; } h4 { font-size: 13px; } ul, ol { padding-left: 22px; } li { margin-bottom: 8px; p { margin-block: 4px; } } pre { font: inherit; white-space: pre-wrap; overflow-wrap: anywhere; margin-block: 6px; } .muted { opacity: .75; font-size: 12px; } details { padding: 12px 0; border-top: 1px solid var(--el-border-color-light); > summary { cursor: pointer; font-weight: 550; } } @media(max-width:600px) { summary { min-height: 44px; display: list-item; align-content: center; } } }
</style>
